 "model": {
  "variables": [
   {
    "name": "logging truck trips",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "lumber carrier vessel trips",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "logging truck trips",
     "coef": 250.0
    },
    {
     "var": "lumber carrier vessel trips",
     "coef": 1000.0
    }
   ]
  },
  "constraints": [
   {
    "name": "trucks_exceed_vessels",
    "terms": [
     {
      "var": "logging truck trips",
